# Rebuilds apps-script/Tracker.gs from core.js + apps-script/tracker-server.js
core=open('core.js').read().replace("if (typeof module !== 'undefined' && module.exports) module.exports = TrackerCore;\n","")
srv=open('apps-script/tracker-server.js').read()
hdr="""/**
 * RealtorOne Pod Tracker (daily accountability check-ins). Add this as a SECOND script file named "Tracker" in the same
 * Apps Script project as the Live Lab feedback Code.gs. It reuses the Live Lab admin login (same username + password).
 * GENERATED by build-gs.py from core.js + apps-script/tracker-server.js. Edit those, not this file.
 */
"""
open('apps-script/Tracker.gs','w').write(hdr+core+"\n"+srv)
